package br.com.minhagibiteca.catalog.presentation;
import br.com.minhagibiteca.auth.application.CurrentAuthenticatedUser; import br.com.minhagibiteca.catalog.application.*; import br.com.minhagibiteca.catalog.domain.Edition; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.core.io.Resource; import org.springframework.data.domain.*; import org.springframework.http.CacheControl; import org.springframework.http.MediaType; import org.springframework.http.ResponseEntity; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller public class EditionController { private final EditionService editions; private final PublisherService publishers; private final ComicSeriesService series; private final WorkService works; private final CreatorService creators; private final EditionAssociationService associations; private final EditionCoverService covers; private final CurrentAuthenticatedUser user; public EditionController(EditionService e,PublisherService p,ComicSeriesService s,WorkService w,CreatorService c,EditionAssociationService a,EditionCoverService coverService,CurrentAuthenticatedUser u){editions=e;publishers=p;series=s;works=w;creators=c;associations=a;covers=coverService;user=u;}
 @GetMapping("/edicoes") String list(@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="0")int page,Model m){m.addAttribute("editions",editions.list(user.id(),q,PageRequest.of(Math.max(0,page),20,Sort.by("normalizedTitle"))));m.addAttribute("query",q);return "edicoes/list";}
 @GetMapping("/edicoes/nova") String n(Model m){m.addAttribute("editionForm",new EditionForm());return form(m,"Nova edição","/edicoes");}
 @PostMapping("/edicoes") String c(@Valid @ModelAttribute("editionForm")EditionForm f,BindingResult r,Model m,RedirectAttributes a){if(r.hasErrors())return form(m,"Nova edição","/edicoes");Edition edition=editions.create(user.id(),cmd(f));associations.replace(edition.getId(),user.id(),f.getWorkIds(),f.getCreatorIds());a.addFlashAttribute("successMessage","Edição cadastrada com sucesso.");return "redirect:/edicoes";}
 @GetMapping("/edicoes/{id}") String detail(@PathVariable UUID id,Model m){m.addAttribute("edition",editions.findOwned(id,user.id()));m.addAttribute("works",associations.works(id,user.id()));m.addAttribute("creators",associations.creators(id,user.id()));return "edicoes/detail";}
 @PostMapping("/edicoes/{id}/capa") String cover(@PathVariable UUID id,@RequestParam("cover") MultipartFile file,RedirectAttributes a){try{covers.replace(id,user.id(),file);a.addFlashAttribute("successMessage","Capa atualizada com sucesso.");}catch(EditionCoverService.InvalidCoverException e){a.addFlashAttribute("errorMessage",e.getMessage());}return "redirect:/edicoes/"+id;}
 @GetMapping("/edicoes/{id}/capa") ResponseEntity<Resource> cover(@PathVariable UUID id){EditionCoverService.Cover cover=covers.load(id,user.id());return ResponseEntity.ok().contentType(MediaType.parseMediaType(cover.contentType())).cacheControl(CacheControl.noStore()).body(cover.resource());}
 @GetMapping("/edicoes/{id}/editar") String e(@PathVariable UUID id,Model m){Edition x=editions.findOwned(id,user.id()); EditionForm f=new EditionForm();f.setPublisherId(x.getPublisherId());f.setSeriesId(x.getSeriesId());f.setTitle(x.getTitle());f.setEditorialNumber(x.getEditorialNumber());f.setVariant(x.getVariant());f.setIsbn(x.getIsbn());f.setPublicationYear(x.getPublicationYear());f.setFormat(x.getFormat());f.setNotes(x.getNotes());f.setWorkIds(associations.workIds(id));f.setCreatorIds(associations.creatorIds(id));m.addAttribute("editionForm",f);return form(m,"Editar edição","/edicoes/"+id+"/editar");}
 @PostMapping("/edicoes/{id}/editar") String u(@PathVariable UUID id,@Valid @ModelAttribute("editionForm")EditionForm f,BindingResult r,Model m,RedirectAttributes a){if(r.hasErrors())return form(m,"Editar edição","/edicoes/"+id+"/editar");editions.update(id,user.id(),cmd(f));associations.replace(id,user.id(),f.getWorkIds(),f.getCreatorIds());a.addFlashAttribute("successMessage","Edição atualizada com sucesso.");return "redirect:/edicoes/"+id;}
 @PostMapping("/edicoes/{id}/excluir") String d(@PathVariable UUID id,RedirectAttributes a){editions.delete(id,user.id());a.addFlashAttribute("successMessage","Edição excluída com sucesso.");return "redirect:/edicoes";}
 private String form(Model m,String title,String action){m.addAttribute("pageTitle",title);m.addAttribute("formAction",action);m.addAttribute("publishers",publishers.options(user.id()));m.addAttribute("seriesPage",series.list(user.id(),"",PageRequest.of(0,200,Sort.by("normalizedName"))));m.addAttribute("works",works.options(user.id()));m.addAttribute("creators",creators.options(user.id()));return "edicoes/form";}
 private EditionService.Command cmd(EditionForm f){return new EditionService.Command(f.getPublisherId(),f.getSeriesId(),f.getTitle(),f.getEditorialNumber(),f.getVariant(),f.getIsbn(),f.getPublicationYear(),f.getFormat(),f.getNotes());}}
